Translate("ptBR", "loch-modan", {
	title = "Loch Modan",
	sections = {
		{
			title = "Resumo",
			text = [=[Loch Modan é uma ampla bacia de colinas e bosques de pinheiros em Khaz Modan, a leste de {link:dun-morogh}Dun Morogh{/link}. Em seu coração fica {link:the-loch}o Loch{/link}, o grande lago que dá nome à terra, contido em sua extremidade norte pelo {link:stonewrought-dam}Dique Lapidado{/link}. A cidade de {link:thelsamar}Thelsamar{/link} fica perto de sua margem oeste. Torres anãs guardam os desfiladeiros que seguem a oeste para {link:ironforge}Altaforja{/link}, ao norte para o {link:wetlands}Pantanal{/link} e ao sul em direção à {link:searing-gorge}Garganta Abrasadora{/link}. É uma terra mais amena que as neves de Dun Morogh, rica em minério, caça e peixe, e os {link:dwarves}anões{/link} do {link:kingdom-of-ironforge}Reino de Altaforja{/link} há muito a consideram sua.]=],
		},
		{
			title = "Origens",
			text = [=[Nenhuma crônica registra quando os anões se estabeleceram pela primeira vez nas margens do {link:the-loch}Loch{/link}, nem quando o {link:stonewrought-dam}Dique Lapidado{/link} foi erguido. A terra é antiga em sua história. No {link:valley-of-kings}Vale dos Reis{/link}, duas grandes estátuas vigiam a estrada do sul. Elas homenageiam Madoran Bronzebeard e Khardros Wildhammer, que lideraram seus clãs na era da Guerra dos Três Martelos. Conta-se que os filhos deles ergueram as estátuas depois dessa guerra para vigiar a estrada do sul, como aviso a qualquer um que voltasse a marchar contra os reinos anões.]=],
		},
		{
			title = "Nos Dias de Hoje",
			text = [=[Loch Modan é uma terra sitiada, e seus defensores são poucos. A Reserva de {link:ironforge}Altaforja{/link} foi chamada para lutar pela {link:alliance}Aliança{/link} em frentes distantes, e os reforços prometidos ao {link:the-loch}Loch{/link} nunca chegaram. O {link:captain-rugelfuss}Capitão Rugelfuss{/link} defende o {link:valley-of-kings}Vale dos Reis{/link} com um único regimento, enquanto os {link:troggs}troggs{/link} da {link:stonesplinter-troggs}tribo Lascapedra{/link} fervilham das colinas do sul e tomam a escavação da {link:explorers-league}Liga dos Exploradores{/link} junto ao lago. {link:ogres}Ogros{/link} do {link:mo-grosh-ogres}clã Mo'grosh{/link} atacam a partir do nordeste. {link:kobolds}Kobolds{/link} tomaram a {link:silver-stream-mine}Mina da Prata{/link}. Pior de tudo, sabotadores {link:dark-iron-dwarves}Ferro Negro{/link} se esgueiraram até o próprio dique, e eles têm amigos entre aqueles em quem os anões confiam. Em {link:thelsamar}Thelsamar{/link}, o {link:magistrate-bluntnose}Magistrado Bluntnose{/link} ouviu que precisa esperar meses por um punhado de soldados. Ele parou de esperar e paga em boa moeda qualquer estranho disposto a lutar.]=],
		},
		{
			title = "Habitantes",
			text = [=[• {b}Os anões de {link:ironforge}Altaforja{/link}.{/b} Montanhistas, mineiros, pescadores e cozinheiros vivem em {link:thelsamar}Thelsamar{/link} e guarnecem as torres ao longo dos desfiladeiros.
• {b}A Liga dos Exploradores.{/b} De sua filial em Thelsamar, a {link:explorers-league}Liga dos Exploradores{/link} abastece a escavação do {link:prospector-ironband}Prospector Ironband{/link} entre as ruínas a leste do lago.
• {b}Os caçadores do {link:the-farstrider-lodge}Pavilhão dos Andarilhos{/link}.{/b} {link:dwarves}Anões{/link}, humanos e uma alta elfa mantêm um pavilhão de caça nas colinas do leste.
• {b}Os {link:stonesplinter-troggs}troggs Lascapedra{/link}.{/b} Dominam os vales do sul, as ilhas do {link:the-loch}Loch{/link} e as ruínas da escavação.
• {b}Os {link:mo-grosh-ogres}ogros Mo'grosh{/link}.{/b} Um clã de {link:ogres}ogros{/link} fez sua fortaleza nas cavernas do nordeste.
• {b}Os {link:tunnel-rat-kobolds}kobolds Tunnel Rat{/link}.{/b} {link:kobolds}Kobolds{/link} cavaram tocas nos contrafortes do oeste e encheram a {link:silver-stream-mine}Mina da Prata{/link}.
• {b}Os {link:dark-iron-dwarves}Ferro Negro{/link}.{/b} Sapadores e insurgentes rondam o dique, e pelo menos um de seus agentes se escondeu entre os próprios carregadores dos anões.]=],
		},
		{
			title = "História",
			text = [=[• {b}Os Três Martelos.{/b} Depois da guerra dos três clãs, os reis dos Bronzebeard e dos Martelo Feroz foram lembrados em pedra no portão sul do {link:the-loch}Loch{/link}.
• {b}A Segunda Guerra.{/b} Quando a {link:horde}Horda{/link} invadiu Khaz Modan na {link:second-war}Segunda Guerra{/link}, a região do Loch caiu sob domínio {link:orcs}orc{/link}. Os anões a reconquistaram, mas os destroços de catapultas e carroças orcs ainda jazem nas águas rasas e atrás da velha mina de prata.
• {b}A Escavação.{/b} A {link:explorers-league}Liga dos Exploradores{/link} abriu uma escavação entre ruínas antigas a sudeste do Loch. Seus escavadores encontraram estranhos ídolos entalhados e, logo depois, os troggs saíram do chão.
• {b}Nos Dias de Hoje.{/b} Agora o Loch é guardado pelos poucos que ficaram e pela ajuda que conseguem contratar.]=],
		},
		{
			title = "Saber do Loch",
			text = [=[• {link:thelsamar}Thelsamar{/link} é famosa por suas linguiças de sangue: carne de urso, enfiada em tripas de javali e temperada com icor de aranha. A cozinheira insiste que é mais difícil do que parece.
• Os crocoliscos do {link:the-loch}Loch{/link} são valorizados pela pele e pela carne, mas se entrincheiraram nas ilhas do lago, e poucos caçadores os abatem sem ganhar uma cicatriz.
• Os montanhistas do Loch bebem Shimmer Stout, fabricada na distante {link:brewnall-village}Aldeia da Cevada{/link}. Um que a provou jurou que ela deixou seus membros tão leves que ele sentiu que podia voar.
• A neve cobre o {link:south-gate-pass}Desfiladeiro do Portão Sul{/link} o ano inteiro, embora as margens do Loch lá embaixo sejam verdes.]=],
		},
	},
})

Translate("ptBR", "thelsamar", {
	title = "Thelsamar",
	aliases = { "Estalagem Pilsen" },
	sections = {
		{
			title = "Resumo",
			text = [=[Thelsamar é a principal cidade de {link:loch-modan}Loch Modan{/link}, um conjunto de casas de pedra perto da margem oeste do lago. Seu coração é a Estalagem Pilsen, e a cidade nunca tem falta de trabalhadores famintos e crianças correndo. Tem uma forja, um poleiro de grifos e uma filial da {link:explorers-league}Liga dos Exploradores{/link}, e um cartaz de procurado de um chefe {link:ogres}ogro{/link} está pendurado em sua rua. O {link:mountaineer-kadrell}Montanhista Kadrell{/link} percorre a estrada que atravessa a cidade, e o {link:magistrate-bluntnose}Magistrado Bluntnose{/link} mantém a ordem. Thelsamar não tem muitos dos confortos de {link:ironforge}Altaforja{/link}: seu ferreiro está sempre sem bronze e gostaria que algum comerciante trouxesse carvão para a cidade.]=],
		},
	},
})

Translate("ptBR", "stonewrought-dam", {
	title = "Dique Lapidado",
	sections = {
		{
			title = "Resumo",
			text = [=[O Dique Lapidado fecha a extremidade norte do {link:the-loch}Loch{/link}, uma muralha de pedra anã tão vasta que o próprio lago repousa contra ela. O {link:chief-engineer-hinderweir-vii}Engenheiro-chefe Hinderweir VII{/link} cuida dele, com alguns engenheiros e montanhistas. A maior parte de seus guardas foi enviada para o front, inclusive seu inspetor-chefe. A perda é sentida. Os {link:dark-iron-dwarves}Ferro Negro{/link} já destruíram a {link:thandol-span}Ponte Thandol{/link} e saquearam {link:dun-modr}Dun Modr{/link}, ao norte, e Hinderweir tem certeza de que o dique é o próximo. Seus sapadores foram vistos na rampa leste.]=],
		},
	},
})

Translate("ptBR", "algaz-station", {
	title = "Estação Algaz",
	aliases = { "torre de guarda do norte" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Estação Algaz é o posto de guarda do norte de {link:loch-modan}Loch Modan{/link}. Sua torre fica onde o túnel do Desfiladeiro do Portão Norte desce de {link:dun-morogh}Dun Morogh{/link}, logo ao sul de {link:dun-algaz}Dun Algaz{/link}, o desfiladeiro que segue para o {link:wetlands}Pantanal{/link}. Muitos montanhistas estão alocados aqui. Do alto da torre, o {link:mountaineer-stormpike}Montanhista Stormpike{/link} vigia as estradas e fala de bom grado de suas próprias façanhas. Um armeiro e um mercador itinerante servem a guarnição. Ao norte da estação, os montanhistas que guardam Dun Algaz encontraram a estrada à frente infestada de orcs.]=],
		},
	},
})

Translate("ptBR", "silver-stream-mine", {
	title = "Mina da Prata",
	sections = {
		{
			title = "Resumo",
			text = [=[A Mina da Prata fica no norte de {link:loch-modan}Loch Modan{/link}, entre a {link:algaz-station}Estação Algaz{/link} e o dique. Deu prata aos anões por muitos anos antes de se esgotar. A Liga dos Mineiros então a transformou num depósito e a encheu de caixotes de boas ferramentas anãs. Agora os {link:tunnel-rat-kobolds}kobolds Tunnel Rat{/link} se mudaram para lá e puseram as patas em tudo. Os montanhistas pretendem limpar a mina, mas a Liga gostaria que seu equipamento fosse retirado primeiro, antes que os soldados o quebrem.]=],
		},
	},
})

Translate("ptBR", "ironband-s-excavation-site", {
	title = "Sítio de Escavação de Bandaferro",
	aliases = { "Escavação de Bandaferro" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Sítio de Escavação de Bandaferro é uma escavação da {link:explorers-league}Liga dos Exploradores{/link} entre ruínas antigas a sudeste do {link:the-loch}Loch{/link}. O {link:prospector-ironband}Prospector Ironband{/link} a lidera, com {link:magmar-fellhew}Magmar Fellhew{/link} para gerenciar o trabalho. Os escavadores tinham acabado de desenterrar um grande número de ídolos de pedra entalhados quando os {link:stonesplinter-troggs}troggs Lascapedra{/link} surgiram nas ruínas e os expulsaram. Os ídolos parecem atrair os troggs e deixar alguns deles enlouquecidos. Os escavadores fugiram tão depressa que deixaram para trás a maior parte das ferramentas. Um chefe {link:troggs}trogg{/link} e seu xamã agora dominam o sítio.]=],
		},
	},
})

Translate("ptBR", "mo-grosh-stronghold", {
	title = "Fortaleza Mo'grosh",
	sections = {
		{
			title = "Resumo",
			text = [=[A Fortaleza Mo'grosh é um ninho de cavernas nas colinas a nordeste do {link:the-loch}Loch{/link}. Um clã de ogros montou acampamento ali e, a partir dele, ataca {link:thelsamar}Thelsamar{/link}, o dique e a escavação. Eles mineram cristais raros nas cavernas. Não faz muito tempo, emboscaram uma caravana de minério que vinha do {link:wetlands}Pantanal{/link} e levaram o minério para seu acampamento. Seu chefe, {link:chok-sul}Chok'sul{/link}, é procurado pelo Magistrado de Thelsamar.]=],
		},
	},
})

Translate("ptBR", "the-farstrider-lodge", {
	title = "Pavilhão dos Andarilhos",
	aliases = { "o Pavilhão dos Andarilhos" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Pavilhão dos Andarilhos fica nas colinas do leste de {link:loch-modan}Loch Modan{/link}. Suas vigas altas e telhados amplos são de estilo élfico, e nenhuma crônica registra quem o ergueu. Hoje é um pavilhão de caçadores, onde a habilidade na caça é valorizada acima de tudo. {link:marek-ironheart}Marek Ironheart{/link} negocia ali peles e carne de crocolisco. Uma alta elfa, {link:vyrin-swiftwind}Vyrin Swiftwind{/link}, guarda seus pensamentos para si, e um jovem humano chamado {link:daryl-the-youngling}Daryl{/link} se gaba para quem quiser ouvir. Comerciantes vendem arcos e armas de fogo a quem vem caçar.]=],
		},
	},
})

Translate("ptBR", "valley-of-kings", {
	title = "Vale dos Reis",
	sections = {
		{
			title = "Resumo",
			text = [=[O Vale dos Reis é o canto sudoeste de {link:loch-modan}Loch Modan{/link}, onde a estrada do {link:south-gate-pass}Desfiladeiro do Portão Sul{/link} desce para o verde. Duas grandes estátuas de reis anões, Madoran Bronzebeard e Khardros Wildhammer, erguem-se sobre o vale, voltadas para o sul. Perto dali ergue-se a torre de guarda do sul do {link:captain-rugelfuss}Capitão Rugelfuss{/link}, cujo regimento não ousa deixar o posto por medo de uma invasão. Mais ao sul, um portão trancado leva em direção à {link:searing-gorge}Garganta Abrasadora{/link}, e a {link:mountaineer-pebblebitty}Montanhista Pebblebitty{/link} só o abre para quem prova seu valor.]=],
		},
	},
})

Translate("ptBR", "the-loch", {
	title = "Loch",
	aliases = { "o Loch" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Loch é o grande lago de Khaz Modan, parado e frio sob as colinas. Pescadores trabalham em sua margem oeste, e caçadores procuram os crocoliscos que se entrincheiraram em suas ilhas. Trechadontes nadam em suas profundezas. As ilhas não são seguras: troggs dominam a maior delas e atacaram um aviador {link:gnomes}gnomo{/link} que caiu na água ali perto. Destroços antigos estão espalhados pelas águas rasas, e os pescadores ainda encontram objetos perdidos entre os escombros.]=],
		},
	},
})

Translate("ptBR", "grizzlepaw-ridge", {
	title = "Serra Garracinza",
	sections = {
		{
			title = "Resumo",
			text = [=[A Serra Garracinza ergue-se ao sul de {link:thelsamar}Thelsamar{/link}, entre a cidade e as terras dos troggs no sudoeste. Ela pertence aos ursos. Suas tocas estão espalhadas pelas encostas e, entre elas, vive um urso-negro enorme, {link:ol-sooty}Ol' Sooty{/link}, que os caçadores do {link:the-farstrider-lodge}Pavilhão dos Andarilhos{/link} há muito tentam abater sem sucesso. Os viajantes na estrada abaixo ficam de olho nas colinas, pois o velho urso às vezes desce.]=],
		},
	},
})

Translate("ptBR", "stonesplinter-valley", {
	title = "Vale Lascapedra",
	sections = {
		{
			title = "Resumo",
			text = [=[O Vale Lascapedra serpenteia entre as montanhas do sudoeste de {link:loch-modan}Loch Modan{/link} e deu seu nome aos troggs que agora o lotam. Seus batedores vigiam a estrada, seus videntes e esmaga-crânios dominam as colinas do sul, e seu chefe {link:grawmug}Grawmug{/link} fica na mais profunda de suas cavernas. Os montanhistas que patrulham essa região nem sempre voltam. Foi aqui que a {link:mountaineer-ylva}Montanhista Ylva{/link} veio procurar uma dessas patrulhas perdidas, e aqui que ela tombou.]=],
		},
	},
})

Translate("ptBR", "south-gate-pass", {
	title = "Desfiladeiro do Portão Sul",
	sections = {
		{
			title = "Resumo",
			text = [=[O Desfiladeiro do Portão Sul é o túnel do sul entre {link:dun-morogh}Dun Morogh{/link} e {link:loch-modan}Loch Modan{/link}. Ele vai da torre do Posto de Guarda do Portão Sul, a oeste, até o {link:valley-of-kings}Vale dos Reis{/link}, a leste, e é o caminho mais curto de {link:ironforge}Altaforja{/link} a {link:thelsamar}Thelsamar{/link}. A passagem fica no alto, e a neve se acumula nela o ano inteiro. Um xamã do {link:the-loch}Loch{/link} mandou buscar um pote dela, para um trabalho que não explicou. Montanhistas levam barris de cerveja escura por ali, vindos de Dun Morogh.]=],
		},
	},
})

Translate("ptBR", "captain-rugelfuss", {
	title = "Capitão Rugelfuss",
	subtitle = "Capitão da Torre do Sul",
	found = "A torre de guarda do sul, Vale dos Reis",
	hint = "Fale com o capitão que defende a torre de guarda do sul.",
	allegiance = "Reino de Altaforja · Montanhistas de Altaforja",
	aliases = { "Rugelfuss" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Capitão Rugelfuss comanda o regimento que guarda o portão sul de {link:loch-modan}Loch Modan{/link}, na torre sob as estátuas do {link:valley-of-kings}Vale dos Reis{/link}. Ele não tem paciência para continências. A {link:alliance}Aliança{/link} está sob forte pressão no estrangeiro, diz ele, e isso torna as terras anãs ainda mais preciosas, enquanto os troggs que brotam delas são um perigo grave para o rei.]=],
		},
		{
			title = "Importância",
			text = [=[Rugelfuss é o soldado deixado para segurar a porta. A Reserva de {link:ironforge}Altaforja{/link} foi chamada para o front, e seus poucos montanhistas não podem deixar o portão sem convidar uma invasão. Então ele combate os troggs do único jeito que lhe resta: enviando voluntários às colinas em seu lugar.]=],
		},
		{
			title = "Feitos",
			text = [=[• Defende o portão sul de {link:loch-modan}Loch Modan{/link} com uma fração dos soldados de que precisa.
• Dirige seus montanhistas {link:mountaineer-cobbleflint}Cobbleflint{/link}, Gravelgaw e Wallbang numa longa campanha contra os {link:stonesplinter-troggs}troggs Lascapedra{/link}.
• Descobre o nome do chefe que lidera o levante {link:troggs}trogg{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Os Dentes de Pedra",
			hint = "Traga ao capitão provas de troggs mortos nas colinas.",
			text = [=[Preso a seu portão, Rugelfuss não podia levar a guerra às colinas pessoalmente. Pediu, em vez disso, provas: os dentes de pedra dos troggs mortos além de suas muralhas. Cada dente posto em sua mesa era um {link:troggs}trogg{/link} a menos no vale e um pequeno sinal de que os anões ainda não estavam vencidos.]=],
		},
		{
			title = "O Chefe dos Lascapedra",
			hint = "Ataque o líder do levante trogg.",
			text = [=[Por fim, seus batedores descobriram quem liderava o levante. Os troggs seguiam um chefe chamado {link:grawmug}Grawmug{/link}, que nunca ia a lugar algum sem seus dois guardas mais ferozes, Gnasher e Brawler. Rugelfuss queria os três mortos. Sem seus líderes, julgava ele, os troggs talvez finalmente fossem empurrados de volta para dentro da terra.]=],
		},
		{
			title = "O Estandarte Caído",
			hint = "Descubra o que foi feito da Montanhista Ylva.",
			text = [=[A {link:mountaineer-ylva}Montanhista Ylva{/link} tinha ido sozinha às terras dos troggs procurar uma patrulha que nunca voltou para casa. Foi encontrada morta ao lado de um estandarte de {link:ironforge}Altaforja{/link} pisoteado. Quando o estandarte foi erguido de novo, o {link:troggs}trogg{/link} que a matara saiu para enfrentá-lo e morreu. Rugelfuss levou o estandarte de volta para ser limpo e pendurado na torre. Ylva nunca fora de ter cautela, disse ele. Agora, pelo menos, eles sabiam.]=],
		},
	},
	mentions = {
		{ text = "A Ameaça Trogg" },
		{
			text = [=[Em Defesa das Terras do Rei, a caçada a {link:grawmug}Grawmug{/link}]=],
		},
		{
			text = [=[Em Defesa das Terras do Rei, ordenada por meio de {link:mountaineer-cobbleflint}Cobbleflint{/link}]=],
		},
		{ text = "Estandarte dos Caídos" },
		{ text = "Abastecendo o Front, armas para seus montanhistas" },
	},
	bonds = {
		{ id = "mountaineer-cobbleflint", name = "Montanhista Cobbleflint", note = "serve em sua torre" },
		{ id = "grawmug", name = "Grawmug", note = "o chefe que ele quer morto" },
		{ id = "mountaineer-ylva", name = "Montanhista Ylva", note = "tombou nas terras dos troggs" },
		{ id = "headsplitter", name = "Headsplitter", note = "matou Ylva" },
		{ id = "magni-bronzebeard", name = "Magni Bronzebeard", note = "seu rei" },
	},
})

Translate("ptBR", "chief-engineer-hinderweir-vii", {
	title = "Engenheiro-chefe Hinderweir VII",
	subtitle = "Guardião do Dique Lapidado",
	found = "No alto do Dique Lapidado",
	hint = "Fale com o engenheiro-chefe que vigia o dique.",
	allegiance = "Reino de Altaforja",
	aliases = { "Hinderweir" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Engenheiro-chefe Hinderweir VII cuida do {link:stonewrought-dam}Dique Lapidado{/link}, a grande muralha de pedra que contém {link:the-loch}o Loch{/link}. Ele é o sétimo de seu nome a portar esse título, e nenhuma crônica registra os seis antes dele. É um {link:dwarves}anão{/link} preocupado, e tem motivos para isso. Seu melhor inspetor e a maior parte de seus guardas foram enviados ao front da {link:alliance}Aliança{/link}, e os {link:dark-iron-dwarves}Ferro Negro{/link} estão se movendo no norte.]=],
		},
		{
			title = "Importância",
			text = [=[Hinderweir vê o padrão que os outros não percebem. Primeiro a {link:thandol-span}Ponte Thandol{/link} foi destruída, depois {link:dun-modr}Dun Modr{/link} foi saqueada. Ele não duvida de que o dique seja o próximo alvo do {link:dark-iron-dwarves}clã Ferro Negro{/link} e, se ele cair, {link:the-loch}o Loch{/link} cai junto.]=],
		},
		{
			title = "Feitos",
			text = [=[• Vigia o {link:stonewrought-dam}Dique Lapidado{/link} com uma guarda reduzida.
• Envia uma amostra de pólvora {link:dark-iron-dwarves}Ferro Negro{/link} ao especialista em explosivos de {link:dun-modr}Dun Modr{/link}.
• Prepara a mistura que salva o dique de uma carga Ferro Negro.]=],
