Translate("ptBR", "prospector-ironband", {
	title = "Prospector Ironband",
	subtitle = "Prospector da Liga dos Exploradores",
	found = "Sítio de Escavação de Bandaferro",
	hint = "Encontre o prospector cuja escavação fica a sudeste do Loch.",
	allegiance = "Liga dos Exploradores",
	aliases = { "Ironband", "Darteus Ironband" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Prospector Darteus Ironband lidera a escavação da {link:explorers-league}Liga dos Exploradores{/link} entre as ruínas antigas a sudeste do {link:the-loch}Loch{/link}. Ele é robusto e honesto, e valoriza resultados. Ultimamente teve poucos. Os {link:stonesplinter-troggs}troggs Lascapedra{/link} tomaram seu sítio, sua pólvora explosiva nunca chega, e um de seus colegas prospectores no sul ficou em silêncio.]=],
		},
		{
			title = "Importância",
			text = [=[Ironband é um estudioso em campo. Acredita que os ídolos entalhados de sua escavação podem revelar um elo entre os troggs e os titãs, e persegue essa questão de {link:loch-modan}Loch Modan{/link} aos {link:badlands}Ermos{/link}. O que ele descobre chega à Liga em {link:ironforge}Altaforja{/link}.]=],
		},
		{
			title = "Feitos",
			text = [=[• Lidera a escavação e escreve seus relatórios para a Liga.
• Pede repetidas vezes a pólvora explosiva que é enviada e nunca chega.
• Manda buscar notícias do Prospector Agmond, que liderava as escavações da Liga nos {link:badlands}Ermos{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Os Ídolos Entalhados",
			hint = "Leve o relatório do prospector a Thelsamar.",
			text = [=[O relatório de Ironband é curto e paciente. A escavação continua, atrasada por troggs mais agressivos que o normal. A maioria dos achados é interessante e nada mais. Um não é: os ídolos entalhados atraem os troggs e deixam alguns deles enlouquecidos. É preciso estudar mais. E, mais uma vez, onde está sua pólvora explosiva?]=],
		},
		{
			title = "A Pólvora Desaparecida",
			hint = "Garanta que a pólvora chegue em segurança à escavação.",
			text = [=[{link:jern-hornhelm}Jern Hornhelm{/link} tinha enviado pólvora semanas antes, e ela nunca chegou. O carregamento seguinte foi levado por carregadores ao longo da curva do {link:the-loch}Loch{/link} e, na estrada, os {link:dark-iron-dwarves}Ferro Negro{/link} atacaram. Um dos carregadores, Saean, era homem deles, embora trabalhasse ao lado dos outros havia quase um ano. Quando Miran finalmente trouxe o resto da pólvora, Ironband ficou contente, e inquieto por os Ferro Negro terem amigos capazes de pôr as mãos em coisas assim.]=],
		},
		{
			title = "O Destino de Agmond",
			hint = "Descubra o que aconteceu ao Prospector Agmond nos Ermos.",
			text = [=[O corpo de Agmond foi encontrado nos {link:badlands}Ermos{/link}, destroçado e descarnado, com uma única palavra riscada no arenito por sua mão: {link:murdaloc}Murdaloc{/link}. Ironband o chorou como um lutador de crânio duro e golpe pesado. Temia que as urnas encontradas pelos escavadores de Agmond tivessem despertado os troggs, assim como seus próprios ídolos.]=],
		},
	},
	mentions = {
		{ text = "Relatório de Progresso da Escavação" },
		{ text = "Pólvora para Ironband" },
		{ text = "Protegendo o Carregamento" },
		{ text = "Ferramentas da Escavação, recuperadas das ruínas" },
		{ text = "Ironband Quer Você!" },
		{ text = "Encontre Agmond" },
		{ text = "{link:murdaloc}Murdaloc{/link}" },
		{ text = "O Destino de Agmond" },
	},
	bonds = {
		{ id = "magmar-fellhew", name = "Magmar Fellhew", note = "administra seu sítio" },
		{ id = "jern-hornhelm", name = "Jern Hornhelm", note = "seu contato em Thelsamar" },
		{ id = "prospector-stormpike", name = "Prospector Stormpike", note = "envia-lhe ajuda de Altaforja" },
		{ id = "stonesplinter-troggs", name = "troggs Lascapedra", note = "dominam sua escavação" },
	},
})

Translate("ptBR", "magistrate-bluntnose", {
	title = "Magistrado Bluntnose",
	subtitle = "Magistrado de Thelsamar",
	found = "Thelsamar",
	hint = "Fale com o magistrado que governa Thelsamar.",
	allegiance = "Thelsamar · Reino de Altaforja",
	aliases = { "Bluntnose" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Magistrado Bluntnose governa {link:thelsamar}Thelsamar{/link} e está perdendo a paciência com {link:ironforge}Altaforja{/link}. Levou dois meses para saber que a cidade receberia alguns soldados, e disseram-lhe que serão mais dois até que cheguem. Enquanto isso, Thelsamar, a escavação e o dique estão expostos a ataques.]=],
		},
		{
			title = "Importância",
			text = [=[Bluntnose é a voz da gente comum do {link:the-loch}Loch{/link}. Enquanto os capitães pedem soldados que nunca chegam, o magistrado mete a mão na bolsa da cidade e contrata quem estiver disposto a lutar. Por meio dele, a defesa de {link:loch-modan}Loch Modan{/link} passa para as mãos de estranhos.]=],
		},
		{
			title = "Feitos",
			text = [=[• Contrata mercenários contra os {link:mo-grosh-ogres}ogros Mo'grosh{/link} do nordeste.
• Põe a prêmio a cabeça de {link:chok-sul}Chok'sul{/link}, o {link:ogres}ogro{/link} que ele acredita liderar os ataques à sua cidade.
• Pretende se voltar contra os troggs assim que os ogros forem resolvidos.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Pouco está escrito sobre a vida de Bluntnose antes de seu cargo. Este registro guarda apenas o que sua cidade e suas ordens revelam.]=],
		},
	},
	chapters = {
		{
			title = "Braços Contratados",
			hint = "Aceite a moeda do magistrado e combata os ogros do nordeste.",
			text = [=[Os ogros tinham montado acampamento na margem nordeste do lago, e não havia ninguém para mandar contra eles. Então Bluntnose mandou estranhos. Quando voltaram com a notícia de ogros mortos, ele ficou encantado. Com os ogros sob controle, disse, a cidade enfim poderia se voltar contra os troggs.]=],
		},
		{
			title = "A Cabeça de Chok'sul",
			hint = "Atenda ao cartaz de procurado pendurado em Thelsamar.",
			text = [=[Em {link:thelsamar}Thelsamar{/link} há um aviso com o selo do magistrado. Ele nomeia {link:chok-sul}Chok'sul{/link}, o {link:ogres}ogro{/link} que se supõe liderar e planejar os ataques à cidade, ao dique e à escavação, e promete moedas por uma prova de sua morte. Quando essa prova foi posta diante dele, Bluntnose recuou diante da visão e depois pagou de bom grado.]=],
		},
	},
	mentions = {
		{ text = "Mercenários" },
		{ text = "PROCURA-SE: {link:chok-sul}Chok'sul{/link}" },
	},
	bonds = {
		{ id = "chok-sul", name = "Chok'sul", note = "o ogro que ele quer morto" },
		{ id = "mountaineer-kadrell", name = "Montanhista Kadrell", note = "guarda a estrada que atravessa sua cidade" },
	},
})

