Translate("ptBR", "stonesplinter-troggs", {
	title = "Troggs Lascapedra",
	aliases = { "Lascapedra", "troggs Lascapedra", "tribo Lascapedra" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Lascapedra são os {link:troggs}troggs{/link} de {link:loch-modan}Loch Modan{/link}. Tiram seu nome do {link:stonesplinter-valley}Vale Lascapedra{/link}, no sudoeste, e são o maior perigo que {link:the-loch}o Loch{/link} enfrenta. Nenhuma crônica registra quando eles subiram pela primeira vez dos lugares profundos daqui.]=],
		},
		{
			title = "Suas Terras",
			text = [=[Dominam o {link:stonesplinter-valley}Vale Lascapedra{/link} e as colinas do sul, onde seu chefe {link:grawmug}Grawmug{/link} ocupa a caverna mais profunda. Tomaram a maior ilha do {link:the-loch}Loch{/link}. No {link:ironband-s-excavation-site}Sítio de Escavação de Bandaferro{/link}, onde surgiram entre as ruínas, um chefe chamado Galgosh e um xamã tribal chamado Magosh dominam as escavações. Suas fileiras têm batedores, esmaga-crânios e quebra-ossos, além de videntes, xamãs e geomantes que praticam uma magia rudimentar da terra.]=],
		},
		{
			title = "Nos Dias de Hoje",
			text = [=[Os Lascapedra são atraídos pelos ídolos entalhados da escavação, e alguns deles enlouquecem por causa dos ídolos. O {link:prospector-ironband}Prospector Ironband{/link} espera que os ídolos um dia expliquem o laço entre os troggs e os titãs. Até lá, os montanhistas da torre do sul os combatem com o pouco que têm. Eles contam os troggs que matam por seus dentes de pedra.]=],
		},
	},
})

