		{
			title = "Seus Costumes",
			text = [=[São brutamontes, executores e xamãs, com místicos entre eles, e seguem um chefe chamado {link:chok-sul}Chok'sul{/link}. Mineram cristais em suas cavernas, tão raros que os anões precisam lutar por um único. Atacam as estradas do {link:the-loch}Loch{/link} e são culpados pelos ataques a {link:thelsamar}Thelsamar{/link}, ao {link:stonewrought-dam}Dique Lapidado{/link} e à escavação. Certa vez emboscaram uma caravana de minério que seguia do {link:wetlands}Pantanal{/link} para Thelsamar e levaram o minério para seu acampamento.]=],
		},
		{
			title = "Nos Dias de Hoje",
			text = [=[O Magistrado de {link:thelsamar}Thelsamar{/link} contratou mercenários para derrotá-los, e há um prêmio sobre a cabeça de {link:chok-sul}Chok'sul{/link}. O magistrado quer os ogros resolvidos primeiro, para que a cidade possa enfim se voltar contra os troggs.]=],
		},
	},
})

